/*
 * ========================================
 * ITEM MAPPINGS - Lago to QuickBooks
 * ========================================
 * Configure mappings between Lago codes and QuickBooks IDs.
 * This node is referenced by invoice and credit note processing.
 *
 * To add a new mapping, add a line: 'lago_code': 'qb_id'
 */

const MAPPINGS = {
  /*
   * ITEM MAPPINGS
   * Map Lago fees.item.code to QuickBooks Item IDs
   */
  ITEM_MAPPINGS: {
    // 'startup': '1',
    // 'premium': '2',
    // 'api_calls': '3',
  },
  ITEM_FALLBACK_ID: '1',  // Used when no mapping found

  /*
   * TAX MAPPINGS
   * Map Lago applied_taxes.tax_code to QuickBooks TaxCode refs
   * Common QB values: 'TAX' (taxable), 'NON' (non-taxable)
   */
  TAX_MAPPINGS: {
    // 'french_standard_vat': 'TAX',
    // 'us_sales_tax': 'TAX',
    // 'tax_exempt': 'NON',
  },
  TAX_FALLBACK_REF: 'NON',  // Used when no mapping found

  /*
   * DISCOUNT MAPPINGS
   * Map Lago credits.item.code to QuickBooks Discount Account IDs
   */
  DISCOUNT_MAPPINGS: {
    // 'startup_deal': '1',
    // 'loyalty_discount': '2',
  },
  DISCOUNT_FALLBACK_ACCOUNT_ID: '1'  // Used when no mapping found
};

// Pass through the input data and add mappings to _config
const input = $input.first().json;
input._config._mappings = MAPPINGS;
return [{ json: input }];

/*
 * ========================================
 * CONFIGURATION - Edit these values
 * ========================================
 */
const CONFIG = {
  // Lago Settings
  LAGO_WEBHOOK_SECRET: 'your_lago_webhook_secret_here',
  BYPASS_SIGNATURE: true,  // Set to false in production

  // QuickBooks Settings
  QB_ENVIRONMENT: 'sandbox',  // 'sandbox' or 'production'
  QB_REALM_ID: 'your_quickbooks_company_id',
  QB_DEFAULT_ITEM_ID: '1',
  QB_TAX_CODE_ID: '',   // Tax Code ID (TxnTaxCodeRef) - find via: SELECT * FROM TaxCode
  QB_TAX_RATE_ID: '',   // Tax Rate ID (TaxRateRef) - find via: SELECT * FROM TaxRate
  QB_DISCOUNT_ACCOUNT_ID: '1'
};
/* ======================================== */

const item = $input.first();
const body = item.json.body || item.json;
const headers = item.json.headers || {};

if (!CONFIG.BYPASS_SIGNATURE) {
  const crypto = require('crypto');
  const signature = headers['x-lago-signature'] || headers['X-Lago-Signature'] || '';
  const expectedSignature = crypto
    .createHmac('sha256', CONFIG.LAGO_WEBHOOK_SECRET)
    .update(JSON.stringify(body))
    .digest('hex');
  if (signature !== expectedSignature) {
    throw new Error('Invalid webhook signature');
  }
}

// Return the webhook payload with config
return [{
  json: {
    ...body,
    _config: CONFIG,
    _verified: true,
    _receivedAt: new Date().toISOString()
  }
}];

const input = $input.first().json;
const CONFIG = input._config;
const lagoCustomer = input.customer;

const displayName = lagoCustomer.name || 
  [lagoCustomer.firstname, lagoCustomer.lastname].filter(Boolean).join(' ') || 
  lagoCustomer.legal_name || 
  lagoCustomer.external_id;

const qbCustomer = {
  DisplayName: displayName.substring(0, 100),
  CompanyName: lagoCustomer.legal_name || lagoCustomer.name || undefined,
  GivenName: lagoCustomer.firstname || undefined,
  FamilyName: lagoCustomer.lastname || undefined,
  PrimaryEmailAddr: lagoCustomer.email ? { Address: lagoCustomer.email } : undefined,
  PrimaryPhone: lagoCustomer.phone ? { FreeFormNumber: lagoCustomer.phone } : undefined,
  BillAddr: {
    Line1: lagoCustomer.address_line1 || undefined,
    Line2: lagoCustomer.address_line2 || undefined,
    City: lagoCustomer.city || undefined,
    CountrySubDivisionCode: lagoCustomer.state || undefined,
    PostalCode: lagoCustomer.zipcode || undefined,
    Country: lagoCustomer.country || undefined
  },
  CurrencyRef: lagoCustomer.currency ? { value: lagoCustomer.currency } : undefined,
  Notes: `Lago ID: ${lagoCustomer.lago_id}\nExternal ID: ${lagoCustomer.external_id}`
};

const cleanObject = (obj) => {
  Object.keys(obj).forEach(key => {
    if (obj[key] === undefined) delete obj[key];
    else if (typeof obj[key] === 'object' && obj[key] !== null) {
      cleanObject(obj[key]);
      if (Object.keys(obj[key]).length === 0) delete obj[key];
    }
  });
};
cleanObject(qbCustomer);

return [{ json: { qbCustomer, lagoCustomerId: lagoCustomer.lago_id, _config: CONFIG } }];

const input = $input.first().json;
const CONFIG = input._config;
const lagoCustomer = input.customer;

const displayName = lagoCustomer.name || 
  [lagoCustomer.firstname, lagoCustomer.lastname].filter(Boolean).join(' ') || 
  lagoCustomer.legal_name || 
  lagoCustomer.external_id;

const qbCustomer = {
  DisplayName: displayName.substring(0, 100),
  CompanyName: lagoCustomer.legal_name || lagoCustomer.name || undefined,
  GivenName: lagoCustomer.firstname || undefined,
  FamilyName: lagoCustomer.lastname || undefined,
  PrimaryEmailAddr: lagoCustomer.email ? { Address: lagoCustomer.email } : undefined,
  PrimaryPhone: lagoCustomer.phone ? { FreeFormNumber: lagoCustomer.phone } : undefined,
  BillAddr: {
    Line1: lagoCustomer.address_line1 || undefined,
    Line2: lagoCustomer.address_line2 || undefined,
    City: lagoCustomer.city || undefined,
    CountrySubDivisionCode: lagoCustomer.state || undefined,
    PostalCode: lagoCustomer.zipcode || undefined,
    Country: lagoCustomer.country || undefined
  },
  CurrencyRef: lagoCustomer.currency ? { value: lagoCustomer.currency } : undefined,
  Notes: `Lago ID: ${lagoCustomer.lago_id}\nExternal ID: ${lagoCustomer.external_id}`
};

const cleanObject = (obj) => {
  Object.keys(obj).forEach(key => {
    if (obj[key] === undefined) delete obj[key];
    else if (typeof obj[key] === 'object' && obj[key] !== null) {
      cleanObject(obj[key]);
      if (Object.keys(obj[key]).length === 0) delete obj[key];
    }
  });
};
cleanObject(qbCustomer);

return [{ json: { qbCustomer, lagoCustomerId: lagoCustomer.lago_id, _config: CONFIG } }];

let inputData;
try {
  inputData = $('Transform Customer Create').first()?.json;
} catch (e) {
  // Node not executed in this run
}
if (!inputData) {
  try {
    inputData = $('Transform Customer Update').first()?.json;
  } catch (e) {
    // Node not executed in this run
  }
}
if (!inputData) {
  throw new Error('Neither Transform Customer Create nor Transform Customer Update was executed');
}

const queryResponse = $input.first().json;
const CONFIG = inputData._config;

const existingCustomers = queryResponse?.QueryResponse?.Customer || [];
const customerExists = existingCustomers.length > 0;

let qbCustomer = { ...inputData.qbCustomer };
if (customerExists) {
  qbCustomer.Id = existingCustomers[0].Id;
  qbCustomer.SyncToken = existingCustomers[0].SyncToken;
  qbCustomer.sparse = true;
}

return [{ json: { qbCustomer, customerExists, lagoCustomerId: inputData.lagoCustomerId, _config: CONFIG } }];

const input = $input.first().json;
const CONFIG = input._config;
const lagoInvoice = input.invoice;
const lagoCustomer = lagoInvoice.customer;

const centsToDollars = (cents) => Number((cents / 100).toFixed(2));

// Compute customer DisplayName for lookup
const customerDisplayName = (lagoCustomer.name || [lagoCustomer.firstname, lagoCustomer.lastname].filter(Boolean).join(' ') || lagoCustomer.legal_name || lagoCustomer.external_id).substring(0, 100);

const lineItems = [];
let lineNum = 1;
let totalTaxableAmount = 0;

if (lagoInvoice.fees && lagoInvoice.fees.length > 0) {
  for (const fee of lagoInvoice.fees) {
    const description = fee.item?.invoice_display_name || fee.item?.name || fee.description || 'Fee';
    const feeTaxCode = fee.applied_taxes?.[0]?.tax_code || null;
    const hasTax = fee.taxes_rate > 0;
    const feeAmount = centsToDollars(fee.amount_cents);

    if (hasTax) totalTaxableAmount += feeAmount;

    lineItems.push({
      LineNum: lineNum++,
      Amount: feeAmount,
      DetailType: 'SalesItemLineDetail',
      Description: description.substring(0, 4000),
      SalesItemLineDetail: {
        Qty: parseFloat(fee.units) || 1,
        UnitPrice: parseFloat(fee.precise_unit_amount) || feeAmount,
        ItemRef: { value: CONFIG.QB_DEFAULT_ITEM_ID, name: 'Services' },
        TaxCodeRef: { value: hasTax ? 'TAX' : 'NON' }
      },
      _lagoItemCode: fee.item?.code || null,
      _lagoTaxCode: feeTaxCode,
      _lagoTaxRate: fee.taxes_rate || 0
    });
  }
}

if (lagoInvoice.credits && lagoInvoice.credits.length > 0) {
  for (const credit of lagoInvoice.credits) {
    lineItems.push({
      LineNum: lineNum++,
      Amount: centsToDollars(credit.amount_cents),
      DetailType: 'DiscountLineDetail',
      Description: credit.item?.name || 'Credit',
      DiscountLineDetail: { PercentBased: false, DiscountAccountRef: { value: CONFIG.QB_DISCOUNT_ACCOUNT_ID } },
      _lagoDiscountCode: credit.item?.code || null
    });
  }
}

const qbInvoice = {
  CustomerRef: { value: 'PLACEHOLDER' },
  DocNumber: lagoInvoice.number,
  TxnDate: lagoInvoice.issuing_date,
  DueDate: lagoInvoice.payment_due_date,
  CurrencyRef: { value: lagoInvoice.currency },
  Line: lineItems,
  PrivateNote: `Lago Invoice: ${lagoInvoice.lago_id}`,
  CustomerMemo: { value: `Invoice ${lagoInvoice.number}` }
};

// Manual tax override using TxnTaxDetail
const totalTaxAmountCents = lagoInvoice.taxes_amount_cents || 0;
if (totalTaxAmountCents > 0 && CONFIG.QB_TAX_RATE_ID) {
  // Get tax rate from first taxable fee
  let taxPercent = 0;
  for (const fee of (lagoInvoice.fees || [])) {
    if (fee.taxes_rate > 0) {
      taxPercent = fee.taxes_rate;
      break;
    }
  }

  const lagoTaxAmount = centsToDollars(totalTaxAmountCents);

  qbInvoice.TxnTaxDetail = {
    TxnTaxCodeRef: { value: CONFIG.QB_TAX_CODE_ID || '2' },
    TotalTax: lagoTaxAmount,
    TaxLine: [{
      Amount: lagoTaxAmount,
      DetailType: 'TaxLineDetail',
      TaxLineDetail: {
        TaxRateRef: { value: CONFIG.QB_TAX_RATE_ID },
        PercentBased: false,
        NetAmountTaxable: totalTaxableAmount,
        TaxPercent: taxPercent,
        OverrideDeltaAmount: lagoTaxAmount
      }
    }]
  };
}

if (lagoCustomer.email) qbInvoice.BillEmail = { Address: lagoCustomer.email };

return [{ json: { qbInvoice, qbCustomer: { DisplayName: customerDisplayName }, lagoInvoiceId: lagoInvoice.lago_id, lagoInvoiceNumber: lagoInvoice.number, lagoCustomerId: lagoCustomer.lago_id, lagoCustomer: lagoCustomer, _config: CONFIG } }];

/*
 * Map Lago Items to QuickBooks Items
 * This node resolves Lago item codes, tax codes, and discount codes
 * to their QuickBooks equivalents using the configured mappings.
 */
const input = $input.first().json;
const MAPPINGS = input._config._mappings;
const qbInvoice = input.qbInvoice;

// Helper function to get mapped value with fallback
const getMapping = (mappings, key, fallback) => {
  if (!key) return fallback;
  return mappings[key] || fallback;
};

// Process line items and apply mappings
const mappedLines = qbInvoice.Line.map(line => {
  const mappedLine = { ...line };

  if (line.DetailType === 'SalesItemLineDetail' && line.SalesItemLineDetail) {
    const itemCode = line._lagoItemCode;
    const taxRate = line._lagoTaxRate || 0;

    mappedLine.SalesItemLineDetail = {
      ...line.SalesItemLineDetail,
      ItemRef: {
        value: getMapping(MAPPINGS.ITEM_MAPPINGS, itemCode, MAPPINGS.ITEM_FALLBACK_ID),
        name: 'Services'
      },
      TaxCodeRef: { value: taxRate > 0 ? 'TAX' : 'NON' }
    };

    // Clean up temporary fields
    delete mappedLine._lagoItemCode;
    delete mappedLine._lagoTaxCode;
    delete mappedLine._lagoTaxRate;
  }

  if (line.DetailType === 'DiscountLineDetail' && line.DiscountLineDetail) {
    const discountCode = line._lagoDiscountCode;

    mappedLine.DiscountLineDetail = {
      ...line.DiscountLineDetail,
      DiscountAccountRef: {
        value: getMapping(MAPPINGS.DISCOUNT_MAPPINGS, discountCode, MAPPINGS.DISCOUNT_FALLBACK_ACCOUNT_ID)
      }
    };

    delete mappedLine._lagoDiscountCode;
  }

  return mappedLine;
});

const mappedInvoice = {
  ...qbInvoice,
  Line: mappedLines
};

return [{
  json: {
    qbInvoice: mappedInvoice,
    qbCustomer: input.qbCustomer,
    lagoInvoiceId: input.lagoInvoiceId,
    lagoInvoiceNumber: input.lagoInvoiceNumber,
    lagoCustomerId: input.lagoCustomerId,
    lagoCustomer: input.lagoCustomer,
    _config: input._config
  }
}];

/*
 * Prepare customer data for creation in QuickBooks
 * This runs when customer doesn't exist and needs to be created
 */
const invoiceData = $('Map Lago Items to QB').first().json;
const CONFIG = invoiceData._config;

// Get customer data from the invoice flow
const lagoCustomer = invoiceData.lagoCustomer;

const displayName = (lagoCustomer.name || 
  [lagoCustomer.firstname, lagoCustomer.lastname].filter(Boolean).join(' ') || 
  lagoCustomer.legal_name || 
  lagoCustomer.external_id).substring(0, 100);

const qbCustomer = {
  DisplayName: displayName,
  CompanyName: lagoCustomer.legal_name || lagoCustomer.name || undefined,
  GivenName: lagoCustomer.firstname || undefined,
  FamilyName: lagoCustomer.lastname || undefined,
  PrimaryEmailAddr: lagoCustomer.email ? { Address: lagoCustomer.email } : undefined,
  PrimaryPhone: lagoCustomer.phone ? { FreeFormNumber: lagoCustomer.phone } : undefined,
  BillAddr: {
    Line1: lagoCustomer.address_line1 || undefined,
    Line2: lagoCustomer.address_line2 || undefined,
    City: lagoCustomer.city || undefined,
    CountrySubDivisionCode: lagoCustomer.state || undefined,
    PostalCode: lagoCustomer.zipcode || undefined,
    Country: lagoCustomer.country || undefined
  },
  CurrencyRef: lagoCustomer.currency ? { value: lagoCustomer.currency } : undefined,
  Notes: `Lago ID: ${lagoCustomer.lago_id}\nExternal ID: ${lagoCustomer.external_id}`
};

// Clean up undefined values
const cleanObject = (obj) => {
  Object.keys(obj).forEach(key => {
    if (obj[key] === undefined) delete obj[key];
    else if (typeof obj[key] === 'object' && obj[key] !== null) {
      cleanObject(obj[key]);
      if (Object.keys(obj[key]).length === 0) delete obj[key];
    }
  });
};
cleanObject(qbCustomer);

return [{ json: { qbCustomer, invoiceData, _config: CONFIG } }];

/*
 * Finalize Invoice - handles both existing and newly created customers
 */
const invoiceData = $('Map Lago Items to QB').first().json;
const CONFIG = invoiceData._config;

let customerId;

// Check if we came from the 'customer exists' branch or 'customer created' branch
try {
  // Try to get customer from lookup (existing customer path)
  const lookupResult = $('Lookup Customer for Invoice').first().json;
  const existingCustomers = lookupResult?.QueryResponse?.Customer || [];
  if (existingCustomers.length > 0) {
    customerId = existingCustomers[0].Id;
  }
} catch (e) {
  // Lookup not in this execution path
}

if (!customerId) {
  // Try to get customer from create response (new customer path)
  try {
    const createResult = $('Create Customer for Invoice').first().json;
    customerId = createResult?.Customer?.Id;
  } catch (e) {
    // Create not in this execution path
  }
}

if (!customerId) {
  throw new Error(`Could not determine customer ID for invoice ${invoiceData.lagoInvoiceNumber}`);
}

let qbInvoice = { ...invoiceData.qbInvoice };
qbInvoice.CustomerRef = { value: customerId };

return [{ json: { qbInvoice, qbCustomerId: customerId, lagoInvoiceId: invoiceData.lagoInvoiceId, lagoInvoiceNumber: invoiceData.lagoInvoiceNumber, _config: CONFIG } }];

/*
 * Skip duplicate invoice - invoice already exists in QuickBooks
 */
const invoiceData = $('Finalize Invoice').first().json;
const lookupResult = $input.first().json;
const existingInvoice = lookupResult?.QueryResponse?.Invoice?.[0];

console.log(`Invoice ${invoiceData.lagoInvoiceNumber} already exists in QuickBooks as ID: ${existingInvoice?.Id}`);

return [{
  json: {
    skipped: true,
    reason: 'Invoice already exists in QuickBooks',
    lagoInvoiceNumber: invoiceData.lagoInvoiceNumber,
    lagoInvoiceId: invoiceData.lagoInvoiceId,
    qbInvoiceId: existingInvoice?.Id,
    qbDocNumber: existingInvoice?.DocNumber
  }
}];

const input = $input.first().json;
const CONFIG = input._config;
const lagoCreditNote = input.credit_note;
const lagoCustomer = lagoCreditNote.customer;

const centsToDollars = (cents) => Number((cents / 100).toFixed(2));

// Compute customer DisplayName for lookup
const customerDisplayName = (lagoCustomer.name || [lagoCustomer.firstname, lagoCustomer.lastname].filter(Boolean).join(' ') || lagoCustomer.legal_name || lagoCustomer.external_id).substring(0, 100);

const lineItems = [];
if (lagoCreditNote.items && lagoCreditNote.items.length > 0) {
  let lineNum = 1;
  for (const item of lagoCreditNote.items) {
    lineItems.push({
      LineNum: lineNum++,
      Amount: centsToDollars(item.amount_cents),
      DetailType: 'SalesItemLineDetail',
      Description: item.fee?.item?.name || 'Credit Note Item',
      SalesItemLineDetail: { Qty: 1, UnitPrice: centsToDollars(item.amount_cents), ItemRef: { value: CONFIG.QB_DEFAULT_ITEM_ID, name: 'Services' } }
    });
  }
}

if (lineItems.length === 0) {
  lineItems.push({
    LineNum: 1,
    Amount: centsToDollars(lagoCreditNote.total_amount_cents || 0),
    DetailType: 'SalesItemLineDetail',
    Description: `Credit Note: ${lagoCreditNote.reason || 'Adjustment'}`,
    SalesItemLineDetail: { Qty: 1, UnitPrice: centsToDollars(lagoCreditNote.total_amount_cents || 0), ItemRef: { value: CONFIG.QB_DEFAULT_ITEM_ID, name: 'Services' } }
  });
}

const qbCreditMemo = {
  CustomerRef: { value: 'PLACEHOLDER' },
  DocNumber: lagoCreditNote.number,
  TxnDate: lagoCreditNote.issuing_date,
  CurrencyRef: { value: lagoCreditNote.currency },
  Line: lineItems,
  PrivateNote: `Lago Credit Note: ${lagoCreditNote.lago_id}`,
  CustomerMemo: { value: `Credit Note ${lagoCreditNote.number}` }
};

if (lagoCustomer.email) qbCreditMemo.BillEmail = { Address: lagoCustomer.email };

return [{ json: { qbCreditMemo, qbCustomer: { DisplayName: customerDisplayName }, lagoCreditNoteId: lagoCreditNote.lago_id, lagoCreditNoteNumber: lagoCreditNote.number, lagoCustomerId: lagoCustomer.lago_id, _config: CONFIG } }];

const creditNoteData = $('Transform Credit Note').first().json;
const customerQuery = $input.first().json;
const CONFIG = creditNoteData._config;

const existingCustomers = customerQuery?.QueryResponse?.Customer || [];
if (existingCustomers.length === 0) throw new Error(`Customer not found for Lago ID: ${creditNoteData.lagoCustomerId}`);

const customerId = existingCustomers[0].Id;
let qbCreditMemo = { ...creditNoteData.qbCreditMemo };
qbCreditMemo.CustomerRef = { value: customerId };

return [{ json: { qbCreditMemo, qbCustomerId: customerId, lagoCreditNoteId: creditNoteData.lagoCreditNoteId, _config: CONFIG } }];

const input = $input.first().json;
const CONFIG = input._config;
const lagoInvoice = input.invoice;

return [{ json: { lagoInvoiceId: lagoInvoice.lago_id, lagoInvoiceNumber: lagoInvoice.number, paymentStatus: lagoInvoice.payment_status, totalAmountCents: lagoInvoice.total_amount_cents, currency: lagoInvoice.currency, lagoCustomerId: lagoInvoice.customer.lago_id, _config: CONFIG } }];

const paymentInfo = $('Extract Payment Info').first().json;
const invoiceQuery = $('Lookup Invoice for Payment').first().json;
const CONFIG = paymentInfo._config;

const invoices = invoiceQuery?.QueryResponse?.Invoice || [];
if (invoices.length === 0) throw new Error(`Invoice not found: ${paymentInfo.lagoInvoiceNumber}`);

const qbInvoice = invoices[0];
const centsToDollars = (cents) => Number((cents / 100).toFixed(2));

const qbPayment = {
  CustomerRef: { value: qbInvoice.CustomerRef.value },
  TotalAmt: centsToDollars(paymentInfo.totalAmountCents),
  CurrencyRef: { value: paymentInfo.currency },
  Line: [{ Amount: centsToDollars(paymentInfo.totalAmountCents), LinkedTxn: [{ TxnId: qbInvoice.Id, TxnType: 'Invoice' }] }],
  PrivateNote: `Payment for Lago Invoice: ${paymentInfo.lagoInvoiceNumber}`
};

return [{ json: { qbPayment, qbInvoiceId: qbInvoice.Id, lagoInvoiceNumber: paymentInfo.lagoInvoiceNumber, _config: CONFIG } }];

// Log non-succeeded payment status
const paymentInfo = $('Extract Payment Info').first().json;

console.log(`Payment status for invoice ${paymentInfo.lagoInvoiceNumber}: ${paymentInfo.paymentStatus}`);

return [{
  json: {
    message: `Payment status '${paymentInfo.paymentStatus}' logged for invoice ${paymentInfo.lagoInvoiceNumber}`,
    lagoInvoiceId: paymentInfo.lagoInvoiceId,
    status: paymentInfo.paymentStatus
  }
}];
